    )>,
}

impl<'t> Iterator for AscendingFacetSort<'t, '_> {
    type Item = Result<(RoaringBitmap, &'t [u8])>;

    fn next(&mut self) -> Option<Self::Item> {
        while let Some((value, range)) = self.stack.last_mut() {
            if let Some(item) = range.next() {
                let (key, value) = item?;
                let key = FacetGroupKeyCodec::<BytesRefCodec>::bytes_decode(key).unwrap();
                if let Some(level) = key.level {
                    let level_byte = level.to_be_bytes();
                    let range = self.db
                        .remap_types::<Bytes, DecodeIgnore>()
                        .prefix_iter(self.rtxn, &level_byte)?;
                    self.stack.push((value, range));
                }
                return Some(Ok((value, &key.left_bound)));
            }
            self.stack.pop();
        }
        None
    }
