                        ExtractionError {
                            kind,
                            context: ExtractionErrorContext::ExtractingSingleValue,
                        }
                    })?;
                vec![extracted_value]
            }
            ValueKind::Array(ArrayPath {
                repeated_value: _,
                path_to_array,
                value_path_in_array,
