                    let extracted_value = extract_value(value_path_in_array, &mut item)
                        .with_context(|kind| ExtractionError {
                            kind,
                            context: ExtractionErrorContext::ExtractingArrayItem(index),
                        })?;
                    extracted_values.push(extracted_value);
                }

